/* ShadowPlay NEXT — production late-extensions loader (Module/Core).
 * Replaces the retired native-host /mods/list injection (osc_main.cpp) with the
 * same post-load timing and allowlist order, served from /Module/ paths.
 * Manifest: /Module/Core/late-manifest.json (generated by build-profiles.cjs).
 * Elements are deliberately NOT tagged with the host sync marker, or the
 * host's removal pass would strip them.
 */
(function (window, document) {
  'use strict';
  if (window.__spnLateExtensions) return;
  window.__spnLateExtensions = true;
  function inject(manifest) {
    var head = document.head;
    manifest.assets.forEach(function (entry) {
      if (!entry || typeof entry.module !== 'string') return;
      var url = entry.module + '?v=' + encodeURIComponent(entry.v || '1');
      var el;
      if (/\.css$/.test(entry.module)) {
        el = document.createElement('link');
        el.rel = 'stylesheet';
        el.href = url;
      } else {
        el = document.createElement('script');
        el.src = url;
        el.async = false; /* keep allowlist execution order */
      }
      el.onerror = function () {
        if (el.parentNode) el.parentNode.removeChild(el);
      };
      head.appendChild(el);
    });
  }
  function start() {
    fetch('/Module/Core/late-manifest.json', { cache: 'no-store' })
      .then(function (r) {
        if (!r.ok) throw new Error('late-manifest ' + r.status);
        return r.json();
      })
      .then(inject)
      .catch(function (e) { console.warn('[spn-late-extensions] load failed', e); });
  }
  if (document.readyState === 'complete') start();
  else window.addEventListener('load', start);
})(window, document);
